import {CODES,YEARS,DATA_VERSION,ENGINE_VERSION,defaultState,validate,eventsFor} from './engine.mjs?v=2026-11-05.10';
import {DATA_SHA256} from './data/provenance.mjs';
export const defaultView=()=>({years:[2027,2026,2001,1992]});
export const validYears=v=>v&&Object.keys(v).length===1&&Array.isArray(v.years)&&[2,3,4].includes(v.years.length)&&v.years.every(y=>Number.isInteger(y)&&YEARS.includes(y))&&new Set(v.years).size===v.years.length;
export function monthlySeries(result){if(!result.valid)throw Error('Invalid practice inputs');const end=result.years.find(y=>y.year===2027);return result.years.map(y=>({year:y.year,nominal:y.nominalMonthly,CPI:y.nominalMonthly*end.indices.CPI.factor/y.indices.CPI.factor,MEI:y.nominalMonthly*end.indices.MEI.factor/y.indices.MEI.factor,cf:y.cf}));}
export const descendingYears=years=>[...years].sort((a,b)=>b-a);
export function comparisonYears(years){const all=[...years];for(const y of defaultView().years){if(all.length===4)break;if(!all.includes(y))all.push(y);}return descendingYears(all);}
export const serialize=(state,view)=>encodeURIComponent(JSON.stringify({version:DATA_VERSION,state,view:{years:comparisonYears(view.years)}}));
export function restore(value){try{const r=JSON.parse(decodeURIComponent(value)),s=r.state;if(r.version!==DATA_VERSION)return {error:'This saved comparison uses unavailable data. Choose current defaults to continue.'};const keys=Object.keys(defaultState());if(!s||Object.keys(s).some(k=>!keys.includes(k))||!s.mix||Object.keys(s.mix).length!==CODES.length||Object.keys(s.mix).some(k=>!CODES.includes(k))||validate(s).length)return {error:'These saved practice settings are invalid. Choose current defaults to continue.'};let v=r.view;if(!v||Object.keys(v).length===1&&YEARS.includes(v.year))v=defaultView();else if(Object.keys(v).every(k=>['from','to','benchmark','inspect'].includes(k))&&Number.isInteger(v.from)&&Number.isInteger(v.to)&&YEARS.includes(v.from)&&YEARS.includes(v.to)&&v.from<v.to&&['CPI','MEI'].includes(v.benchmark)&&YEARS.includes(v.inspect)){v={years:[v.from,v.to]};}if(!validYears(v))return {error:'Choose two to four distinct years between 1992 and 2027.'};return {state:s,view:{years:comparisonYears(v.years)}};}catch{return {error:'This saved comparison could not be opened.'};}}
const EVENTS=[{year:1997,label:'Work RVU update',detail:'Office-visit work RVUs changed, with a separate work adjustment in the fee calculation.'},{year:1999,label:'Practice-expense transition',detail:'Practice-expense values began transitioning to a resource-based system. Other payment adjustments changed at the same time.'},{year:2007,label:'Office RVU update',detail:'The office E/M review increased work RVUs for established visits including 99213 and 99214. A budget-neutrality adjustment reduced the work component; the modeled yearly payment includes both changes.'},{year:2021,label:'Office E/M revaluation',detail:'Office E/M RVUs and documentation rules changed. This illustration holds your visit mix and volume constant.'},{year:2024,label:'G2211 added',detail:'G2211 became separately payable. This model applies your chosen complexity percentage to established visits.'},{year:2027,label:'B1 / B2 added',detail:'B1 replaces G2211 in the non-QP preset; B2 replaces it in the QP + eligible ACO preset. The full-visit calculation applies the selected uplift to the entire E/M fee.'}];
export function significantEvents(data,state){const valuations=eventsFor(data,state);return EVENTS.filter(e=>e.year>=2024?state.complexity>0&&CODES.some(c=>c.startsWith('9921')&&state.mix[c]>0):e.year===1999||valuations.some(v=>v.year===e.year&&v.type==='valuation')).map(e=>{const v=valuations.find(v=>v.year===e.year&&v.type==='valuation');const increased=v?.changes.filter(c=>c.current.work>c.old.work);return {...e,label:e.year===2027?`${state.profile==='qp'?'B2':'B1'} replaces G2211`:[1997,2007].includes(e.year)&&increased?.length?'Work RVUs increased':e.label,changes:v?.changes||[]};});}
export function monthlyCSV(data,state,result,view){if(!validYears(view)||!result.valid)throw Error('Invalid comparison');const points=monthlySeries(result);const rows=[['Medicare Payment Explorer','Monthly payments'],['Data version',DATA_VERSION],['Engine version',ENGINE_VERSION],['Data SHA256',DATA_SHA256],['2027 calculation','Full visit'],['Inflation currency','Constant 2027 dollars'],['Scenario JSON',JSON.stringify({state,view})],['Practice preset',state.profile],['FFS visits per day (volume input)',state.visits],['Working days per month',state.days],['Complexity share of established visits (%)',state.complexity],['Scope','National allowed amounts including patient share; before practice expenses and collections'],['CPI','BLS annual average through 2025; CBO February 2026 forecast extension for 2026–27'],['MEI','CMS published annual update chain including productivity; not realized practice-cost inflation'],[],['Selected year','Nominal monthly (year dollars)','CPI-adjusted monthly (2027 dollars)','MEI-adjusted monthly (2027 dollars)','CF (year dollars/RVU)'],...comparisonYears(view.years).map(year=>{const p=points.find(p=>p.year===year);return [p.year,p.nominal,p.CPI,p.MEI,p.cf];}),[],['All years','Nominal monthly (year dollars)','CPI-adjusted monthly (2027 dollars)','MEI-adjusted monthly (2027 dollars)','CF (year dollars/RVU)','CPI factor (1992=1)','CPI status','MEI factor (1992=1)','MEI status']];for(const p of points){const y=result.years.find(y=>y.year===p.year);rows.push([p.year,p.nominal,p.CPI,p.MEI,p.cf,y.indices.CPI.factor,y.indices.CPI.status,y.indices.MEI.factor,y.indices.MEI.status]);}rows.push([],['Code','Visit share (%)'],...CODES.map(c=>[c,state.mix[c]]),[],['Source ID','URL','SHA256','Hash scope']);for(const s of data.sources)rows.push([s.id,s.url,s.sha256,s.hash_scope]);return '\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');}
